    if root is None:
        return 0
    left = self.leftHeight(root)
    right = self.rightHeight(root)
    if left == right:
        return (1 << left) - 1             # perfect subtree → closed form
    return 1 + self.countNodes(root.left) + self.countNodes(root.right)

def leftHeight(self, node: TreeNode) -> int:
    h = 0
    while node is not None:                # walk only left children
        h += 1
        node = node.left
    return h

def rightHeight(self, node: TreeNode) -> int:
    h = 0
    while node is not None:                # walk only right children
        h += 1
        node = node.right
    return h

